import { z } from "zod";
import manifest from "@/data/ibge-indicators.json";

/**
 * Single declarative catalog of municipal indicators. The JSON is generated by
 * scripts/ingest/build_ibge_manifest.py from IBGE metadata and also drives the importer,
 * so every option in the app maps to exactly one imported table/variable/category set.
 */
const entrySchema = z.object({
  id: z.string(), alias: z.string(), label: z.string(), name: z.string(), theme: z.string(), unit: z.string(),
  topic: z.string(), log: z.boolean(), year: z.number().int(), source: z.string(), kind: z.string(),
  universe: z.string(), definition: z.string(), synonyms: z.array(z.string()), percentBounded: z.boolean(),
  formula: z.string(), url: z.string(),
  spec: z.object({ table: z.string().optional(), variable: z.string().optional(), num: z.unknown().optional(), den: z.unknown().optional() }).passthrough(),
});
const plannedSchema = z.object({ label: z.string(), theme: z.string(), status: z.enum(["nao_importado", "nao_publicado_municipio"]), reason: z.string() });
const parsed = z.object({ version: z.string(), inventory: z.string(), indicators: z.array(entrySchema), planned: z.array(plannedSchema) }).parse(manifest);

export type CatalogEntry = z.infer<typeof entrySchema>;
export type PlannedEntry = z.infer<typeof plannedSchema>;
export const CATALOG_VERSION = parsed.version;
export const INVENTORY_URL = parsed.inventory;
export const CATALOG: readonly CatalogEntry[] = parsed.indicators;
export const PLANNED: readonly PlannedEntry[] = parsed.planned;

/** Short provenance line: "IBGE Censo Demográfico 2022 · SIDRA 9514". */
export function sourceLine(e: CatalogEntry): string {
  const s = e.spec as { table?: string; num?: { table?: string }; den?: { table?: string } };
  const tables = s.table ? s.table : [s.num?.table, s.den?.table].filter(Boolean).join("+");
  return `${e.source} · SIDRA ${tables}`;
}

/** Accent/case-insensitive normalization for search. */
export const normalize = (s: string) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();

export function searchCatalog<T extends { label: string; group: string; synonyms: readonly string[] }>(items: readonly T[], query: string): T[] {
  const terms = normalize(query).split(/\s+/).filter(Boolean);
  if (!terms.length) return [...items];
  return items.filter((v) => {
    const hay = normalize([v.label, v.group, ...v.synonyms].join(" "));
    return terms.every((t) => hay.includes(t));
  });
}
